using System.Security.Cryptography;
using System.Text.Json;
using System.Text.Json.Nodes;
using NUnit.Framework;
using ObsServices.Core.Imaging;
using ObsServices.Core.Protocol;

namespace ObsServices.Core.Tests;

/// <summary>
/// The pixel hash against the service's shared test vectors (<c>tests/fixtures/pixel_hash/</c> in
/// telescope_control, generated by its <c>tools/gen_pixel_hash_fixtures.py</c> and checked by its Rust,
/// Python and web implementations). A frame this library names differently from the service would fail
/// verification on every upload, so this is the gate for the whole image path.
/// </summary>
public class PixelHashTests {
    /// <summary>The fixtures directory, from the sibling checkout or <c>TELESCOPE_LIBRARY</c>'s parent.</summary>
    public static string? FixturesDir() {
        var (_, library, _) = TelescopeServer.Locate();

        if (library == null) {
            return null;
        }

        var dir = Path.Combine(Path.GetDirectoryName(Path.GetFullPath(library))!, "tests", "fixtures", "pixel_hash");
        return File.Exists(Path.Combine(dir, "pixel_hash.json")) ? dir : null;
    }

    private static IEnumerable<TestCaseData> Cases() {
        var dir = FixturesDir();

        if (dir == null) {
            yield break;
        }

        var doc = JsonNode.Parse(File.ReadAllText(Path.Combine(dir, "pixel_hash.json")))!;

        foreach (var c in doc["cases"]!.AsArray()) {
            yield return new TestCaseData(dir, c!.AsObject()).SetName("Fixture_" + c["file"]!.GetValue<string>().Replace('.', '_'));
        }
    }

    [Test]
    public void FixturesArePresent() {
        if (FixturesDir() == null) {
            Assert.Ignore("telescope_control fixtures not found (set TELESCOPE_LIBRARY or check out the sibling repo)");
        }
    }

    [TestCaseSource(nameof(Cases))]
    public void MatchesTheServicesVector(string dir, JsonObject c) {
        var bytes = File.ReadAllBytes(Path.Combine(dir, c["file"]!.GetValue<string>()));
        var image = Fits.Parse(bytes);

        Assert.That((image.Width, image.Height, image.Bitpix), Is.EqualTo((c["width"]!.GetValue<int>(), c["height"]!.GetValue<int>(), c["bitpix"]!.GetValue<int>())), c["note"]!.GetValue<string>());
        Assert.That(image.Bzero, Is.EqualTo(c["bzero"]?.GetValue<double>() ?? 0.0));
        Assert.That(image.Bscale, Is.EqualTo(c["bscale"]?.GetValue<double>() ?? 1.0));

        foreach (var s in c["samples"]!.AsArray()) {
            var expected = s!["value"] switch {
                JsonValue v when v.TryGetValue<double>(out var d) => d,
                JsonValue v when v.GetValue<string>() == "inf" => double.PositiveInfinity,
                JsonValue v when v.GetValue<string>() == "-inf" => double.NegativeInfinity,
                _ => double.NaN,
            };
            Assert.That((double)image.At(s["x"]!.GetValue<int>(), s["y"]!.GetValue<int>()), Is.EqualTo(expected), $"pixel ({s["x"]}, {s["y"]})");
        }

        var hex = c["hex"]!.GetValue<string>();
        Assert.That(Fits.HashOfPixels(image.Pixels), Is.EqualTo(hex), c["note"]!.GetValue<string>());
        Assert.That(Fits.PixelHash(bytes), Is.EqualTo(hex));
        Assert.That(Fits.HashToBase64(hex), Is.EqualTo(c["base64"]!.GetValue<string>()));
        Assert.That(Fits.HashFromText(c["base64"]!.GetValue<string>()), Is.EqualTo(hex));
        Assert.That(Fits.HashFromText(hex.ToUpperInvariant()), Is.EqualTo(hex));
        Assert.That(Fits.Hex(SHA256.HashData(bytes)), Is.EqualTo(c["file_sha256"]!.GetValue<string>()));

        if (image.Bitpix == 16 && image.Bzero == 32768 && image.Bscale == 1) {
            // the in-memory shortcut names a camera frame the same way
            var u16 = image.Pixels.Select(p => (ushort)p).ToArray();
            Assert.That(Fits.HashOfUInt16(u16), Is.EqualTo(hex));
        }
    }

    [Test]
    public void WritesWhatItReads() {
        var rng = new Random(7);
        var pixels = new ushort[40 * 30];

        for (var i = 0; i < pixels.Length; i++) {
            pixels[i] = (ushort)rng.Next(0, 65536);
        }

        pixels[0] = 0;
        pixels[1] = 65535;
        var fits = Fits.Write(pixels, 40, 30, new[] {
            new FitsCard("OBJECT", "M 31 — Andromeda’s core", "target"),
            new FitsCard("EXPTIME", 120.0, "seconds"),
            new FitsCard("GAIN", 100),
            new FitsCard("TRACKING", true),
            new FitsCard("COMMENT", "written by the test"),
            new FitsCard("BLANKKEY", null),
        });

        Assert.That(fits.Length % Fits.Block, Is.Zero);
        var image = Fits.Parse(fits);
        Assert.That((image.Width, image.Height, image.Bitpix, image.Bzero), Is.EqualTo((40, 30, 16, 32768.0)));
        Assert.That(image.Pixels.Select(p => (ushort)p), Is.EqualTo(pixels));
        Assert.That(Fits.HashOfUInt16(pixels), Is.EqualTo(Fits.HashOfPixels(image.Pixels)));

        // header rules: typographic characters become ASCII, commentary is an array, a blank card is null
        Assert.That(image.Header["OBJECT"]!.GetValue<string>(), Is.EqualTo("M 31 - Andromeda's core"));
        Assert.That(image.Header["EXPTIME"]!.GetValue<double>(), Is.EqualTo(120.0));
        Assert.That(image.Header["GAIN"]!.GetValue<long>(), Is.EqualTo(100));
        Assert.That(image.Header["TRACKING"]!.GetValue<bool>(), Is.True);
        Assert.That(image.Header["COMMENT"]!.AsArray()[0]!.GetValue<string>(), Is.EqualTo("written by the test"));
        Assert.That(image.Header["BLANKKEY"]!.AsArray()[0]!.GetValue<string>(), Is.EqualTo(string.Empty), "a card without `= ` is commentary, as the service reads it");
        Assert.That(image.Header.ContainsKey("END"), Is.False);

        // `KEY     = ` with nothing after the indicator is a keyword without a value: null
        var patched = (byte[])fits.Clone();
        var at = IndexOfCard(patched, "BLANKKEY");
        patched[at + 8] = (byte)'=';
        patched[at + 9] = (byte)' ';
        var header = Fits.ParseHeader(patched).Header;
        Assert.That(header.ContainsKey("BLANKKEY"), Is.True);
        Assert.That(header["BLANKKEY"], Is.Null);
    }

    private static int IndexOfCard(byte[] fits, string key) {
        for (var at = 0; at + Fits.Card <= fits.Length; at += Fits.Card) {
            if (System.Text.Encoding.ASCII.GetString(fits, at, 8).TrimEnd() == key) {
                return at;
            }
        }

        throw new InvalidOperationException($"no card {key}");
    }

    [Test]
    public void StatisticsAgreeBetweenThePaths() {
        var rng = new Random(11);
        var pixels = new ushort[64 * 48];

        for (var i = 0; i < pixels.Length; i++) {
            pixels[i] = (ushort)Math.Clamp(500 + rng.NextDouble() * 40 - 20, 0, 65535);
        }

        pixels[100] = 65535;
        pixels[200] = 0;
        var fromHistogram = Fits.StatsOfUInt16(pixels);
        var fromFloats = Fits.Stats(pixels.Select(p => (float)p).ToArray());

        Assert.That(fromHistogram.Median, Is.EqualTo(fromFloats.Median));
        Assert.That(fromHistogram.Sigma, Is.EqualTo(fromFloats.Sigma).Within(1e-9));
        Assert.That((fromHistogram.Min, fromHistogram.Max), Is.EqualTo((0.0, 65535.0)));
        Assert.That(fromFloats.Min, Is.EqualTo(0.0));
        Assert.That(fromHistogram.Sigma, Is.GreaterThan(5).And.LessThan(30), "a uniform ±20 spread has a robust sigma around 15");

        // an even count: the median is the mean of the two middle values
        Assert.That(Fits.StatsOfUInt16(new ushort[] { 1, 2, 3, 10 }).Median, Is.EqualTo(2.5));
        Assert.That(Fits.Stats(new float[] { 1, 2, 3, 10 }).Median, Is.EqualTo(2.5));
        Assert.That(Fits.Stats(new[] { float.NaN, float.PositiveInfinity }).Median, Is.NaN);
    }

    [Test]
    public void PreviewIsASmallGreyPng() {
        var width = 1200;
        var height = 900;
        var rng = new Random(3);
        var pixels = new ushort[width * height];

        for (var i = 0; i < pixels.Length; i++) {
            pixels[i] = (ushort)(500 + rng.Next(0, 16));
        }

        // a bright star
        for (var y = 440; y < 460; y++) {
            for (var x = 590; x < 610; x++) {
                pixels[y * width + x] = 60000;
            }
        }

        // the block size is the smallest whole number that brings the long side under the cap: 1200 / 5 = 240
        var png = Fits.PreviewPng<ushort>(pixels, width, height, 256);
        Assert.That(Png.Size(png), Is.EqualTo((240, 180)));
        Assert.That(png.Length, Is.LessThanOrEqualTo(Images.MaxPreviewBytes));

        var within = Fits.PreviewWithinLimit<ushort>(pixels, width, height);
        Assert.That(within, Is.Not.Null);
        Assert.That(Png.Size(within!)!.Value.Width, Is.LessThanOrEqualTo(Images.PreviewMaxSide));

        // the float path draws the same picture
        var image = Fits.Parse(Fits.Write(pixels, width, height));
        Assert.That(Fits.PreviewPng(image, 256), Is.EqualTo(png));
    }

    [Test]
    public void DescribesACameraFrameWithoutDecodingItTwice() {
        var width = 320;
        var height = 240;
        var rng = new Random(5);
        var pixels = new ushort[width * height];

        for (var i = 0; i < pixels.Length; i++) {
            pixels[i] = (ushort)(1000 + rng.Next(0, 50));
        }

        var fits = Fits.Write(pixels, width, height, new[] { new FitsCard("IMAGETYP", "LIGHT"), new FitsCard("FILTER", "Ha") });
        var info = new FrameInfo { Kind = ImageKind.Light, Camera = "cam", CapturedAt = 1700000000, ExposureS = 30, Filter = "Ha", Gain = 100, Binning = 1, FileName = "x.fits" };
        var fast = FrameDescriber.Describe(pixels, width, height, fits, info);
        var slow = FrameDescriber.Describe(fits, info);

        Assert.That(fast.Hash, Is.EqualTo(slow.Hash));
        Assert.That(fast.FileSha256, Is.EqualTo(slow.FileSha256));
        Assert.That(fast.PreviewPng, Is.EqualTo(slow.PreviewPng));
        Assert.That(fast.Stats!.Median, Is.EqualTo(slow.Stats!.Median));
        Assert.That((fast.Width, fast.Height, fast.Bitpix, fast.Bytes), Is.EqualTo((width, height, 16, (long)fits.Length)));
        Assert.That(fast.Header!["FILTER"]!.GetValue<string>(), Is.EqualTo("Ha"));
        Assert.That(fast.Header.ContainsKey("SIMPLE"), Is.True);

        var json = ProtocolJson.Encode(fast);
        using var doc = JsonDocument.Parse(json);
        Assert.That(doc.RootElement.GetProperty("type").GetString(), Is.EqualTo("image_captured"));
        Assert.That(doc.RootElement.GetProperty("kind").GetString(), Is.EqualTo("light"));
        Assert.That(doc.RootElement.GetProperty("header").GetProperty("NAXIS1").GetInt32(), Is.EqualTo(width));
        Assert.That(doc.RootElement.TryGetProperty("instrument", out _), Is.False, "nulls are left out");
    }
}
